import json,os,datetime
from pathlib import Path
p=Path('/proc/73940');cwd=os.readlink(p/'cwd');assert p.stat().st_uid==601 and '/lbt_omol_memory_recovery_v1/run/' in cwd
line=(p/'cgroup').read_text().strip();assert line.startswith('0::');base=Path('/sys/fs/cgroup')/line[3:].lstrip('/');rows={}
for parent in [base]+list(base.parents):
 if str(parent) in ('/sys/fs/cgroup/system.slice/slurmstepd.scope','/sys/fs/cgroup/system.slice','/sys/fs/cgroup','/sys/fs','/sys','/'):break
 for name in ('memory.current','memory.max','memory.peak','memory.events','memory.swap.current','memory.swap.max','cpu.stat'):
  f=parent/name
  if f.is_file():rows[str(f)]=f.read_text()
print(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pid':73940,'cwd':cwd,'cgroup':line,'readings':rows},indent=2))
